/**
 * Writes supabase/update-images.sql: points each seeded product (matched by
 * slug) at its local render. Safe to run on a live database: it only touches
 * the images column, so prices/stock edited in admin are kept.
 * Run: npx tsx scripts/gen-image-update-sql.ts
 */
import { writeFileSync } from "node:fs";
import { join } from "node:path";
import { SEED_PRODUCTS } from "../lib/seed";

const q = (s: string) => `'${s.replace(/'/g, "''")}'`;
const lines = [
  "-- GENERATED by scripts/gen-image-update-sql.ts. Replaces the old hotlinked placeholder photos",
  "-- with the generic renders in public/products/. Only the images column is changed.",
  "begin;",
  ...SEED_PRODUCTS.map((p) => `update public.products set images = array[${p.images.map(q).join(", ")}]::text[] where slug = ${q(p.slug)};`),
  "commit;",
  "",
];
writeFileSync(join(__dirname, "..", "supabase", "update-images.sql"), lines.join("\n"));
console.log("Wrote supabase/update-images.sql");
